module regfile_8bit #(
    parameter WIDTH = 8,
    parameter DEPTH = 16,
    parameter ADDR_WIDTH = 4
)(
    input  wire                  clk,        // Clock
    input  wire                  rst_n,      // Active-low reset
    // Read port 1
    input  wire [ADDR_WIDTH-1:0] raddr1,     // Read address 1
    output wire [WIDTH-1:0]      rdata1,     // Read data 1
    // Read port 2
    input  wire [ADDR_WIDTH-1:0] raddr2,     // Read address 2
    output wire [WIDTH-1:0]      rdata2,     // Read data 2
    // Write port
    input  wire                  wen,        // Write enable
    input  wire [ADDR_WIDTH-1:0] waddr,      // Write address
    input  wire [WIDTH-1:0]      wdata       // Write data
);

    // Register array
    reg [WIDTH-1:0] registers [0:DEPTH-1];
    
    // Read ports (combinational)
    assign rdata1 = (raddr1 == 0) ? {WIDTH{1'b0}} : registers[raddr1];
    assign rdata2 = (raddr2 == 0) ? {WIDTH{1'b0}} : registers[raddr2];
    
    // Write port (synchronous)
    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all registers to 0
            for (i = 0; i < DEPTH; i = i + 1) begin
                registers[i] <= {WIDTH{1'b0}};
            end
        end else begin
            // Normal write operation
            if (wen && (waddr != 0)) begin
                registers[waddr] <= wdata;
            end
            // Writes to register 0 are ignored (already handled by waddr != 0 check)
        end
    end

endmodule